import{_ as r,o as a,c as t,ah as i}from"./chunks/framework.Bja9t6Wf.js";const u=JSON.parse('{"title":"Judicial Aftermath: Karl-Heinz Grasser (Buwog Case)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/gericht-grasser.md","filePath":"en/recherche/gericht-grasser.md"}'),s={name:"en/recherche/gericht-grasser.md"};function n(o,e,h,l,c,f){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="judicial-aftermath-karl-heinz-grasser-buwog-case" tabindex="-1">Judicial Aftermath: Karl-Heinz Grasser (Buwog Case) <a class="header-anchor" href="#judicial-aftermath-karl-heinz-grasser-buwog-case" aria-label="Permalink to &quot;Judicial Aftermath: Karl-Heinz Grasser (Buwog Case)&quot;">​</a></h1><p><strong>From the &quot;handsomest finance minister&quot; to a first-instance convict.</strong></p><p>Karl-Heinz Grasser embodied the early rise of the &quot;Young Guns&quot; in Austrian politics. His case is the historical model for the modern intertwining of glamour, power, and corruption.</p><hr><h2 id="the-buwog-affair" tabindex="-1">The Buwog Affair <a class="header-anchor" href="#the-buwog-affair" aria-label="Permalink to &quot;The Buwog Affair&quot;">​</a></h2><ul><li><strong>The Allegation:</strong> Bribery payments in the millions during the sale of 60,000 federal apartments in 2004.</li><li><strong>The Verdict (December 2020):</strong> Grasser was sentenced in the first instance to <strong>eight years in prison</strong> for breach of trust, bribery, and falsification of evidence.</li><li><strong>Current Status (2026):</strong> The case is in the next instance. Grasser denies all allegations and is fighting for his freedom while the piles of files continue to grow.</li></ul><hr><p><em>Sources: First-instance judgment LG Vienna (Buwog), reporting by Standard/Profil.</em></p>',8)])])}const d=r(s,[["render",n]]);export{u as __pageData,d as default};
